    [SupplyParameterFromQuery] public string? SearchKeyword { get; set; }

    private List<Account> _accounts = new();
    private string? _keyword, _alert;

    protected override async Task OnParametersSetAsync()
    {
        _keyword = SearchKeyword;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        var query = db.Accounts.Include(a => a.Customer).AsQueryable();
        if (!string.IsNullOrWhiteSpace(SearchKeyword))
        {
            var kw = SearchKeyword.Trim().ToLower();
            query = query.Where(a => a.Username.ToLower().Contains(kw));
        }
        _accounts = await query.OrderByDescending(a => a.CreatedAt).ToListAsync();
    }

    private void Search() => Nav.NavigateTo(Nav.GetUriWithQueryParameters(Nav.Uri.Split('?')[0],
        new Dictionary<string, object?> { ["searchKeyword"] = string.IsNullOrWhiteSpace(_keyword) ? null : _keyword.Trim() }));

    private async Task ToggleLock(Account acc)
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        var account = await db.Accounts.FindAsync(acc.Id);
        if (account == null || account.Username == "admin") return;
        account.IsActive = !account.IsActive;
        await db.SaveChangesAsync();
        _alert = account.IsActive ? $"Đã MỞ KHÓA: {account.Username}" : $"Đã KHÓA: {account.Username}";
        await LoadAsync();
    }

    private async Task DeleteAsync(Account acc)
    {
        if (!await JS.InvokeAsync<bool>("confirm", "Xóa tài khoản này?")) return;

        await using var db = await DbFactory.CreateDbContextAsync();
        var account = await db.Accounts.FindAsync(acc.Id);
        if (account == null || account.Username == "admin") return;
        db.Accounts.Remove(account);
        await db.SaveChangesAsync();
        _alert = $"Đã xóa tài khoản: {account.Username}";
        await LoadAsync();
    }

